/* liberar / reativar o login de uma pessoa do cadastro (qualquer cargo, menos coordenação) */
var CARGO_LOGIN = { vend: 'Vendedor(a)', ger: 'Gerente', sup: 'Supervisor de Loja', anl: 'Analista' };
function usuarioLiberar(d) {
  try {
    if (String(d.chave || '') !== ARQ_SEGREDO) return json({ ok: false, erro: 'não autorizado' });
    var aba = abaUsuarios();
    var dados = aba.getLastRow() >= 2 ? aba.getRange(2, 1, aba.getLastRow() - 1, CAB_USUARIOS.length).getValues() : [];
    var pin = String(d.pin || '').trim();
    if (!/^\d{4,6}$/.test(pin)) return json({ ok: false, erro: 'O PIN inicial tem de 4 a 6 dígitos.' });
    var nomes = [d.nome].concat(d.apelidos || []), j = -1;
    for (var k = 0; k < nomes.length && j < 0; k++) if (nomes[k]) j = linhaUsuarioExata(dados, nomes[k]);
    var loja = String(d.loja || '').trim();
    if (j >= 0) {
      var papel = norm(String(dados[j][2] || ''));
      if (papel.indexOf('coorden') >= 0 || String(dados[j][3] || '').trim() === 'todos') return json({ ok: false, erro: 'Acesso da coordenação só se muda na planilha.' });
      aba.getRange(j + 2, 2).setValue(pin);
      aba.getRange(j + 2, 5).setValue('Sim');
      if (loja && !String(dados[j][8] || '').trim()) aba.getRange(j + 2, 9).setValue(loja);
      aba.getRange(j + 2, COL_TROCAR_PIN + 1).setValue('Sim');
      prazoTrocaLimpar_(dados[j][0]);
      return json({ ok: true, nome: String(dados[j][0]).trim(), novo: false });
    }
    var cargo = CARGO_LOGIN[String(d.cargo || '')];
    if (!cargo) return json({ ok: false, erro: 'Defina o cargo da pessoa no cadastro antes de liberar o acesso.' });
    var nome = nomeBonitoGs(d.nome);
    if (nome.split(' ').length < 2) return json({ ok: false, erro: 'Use nome e sobrenome (como no crachá).' });
    aba.appendRow([nome, pin, cargo, '', 'Sim', '', '', 'Não', loja, 'Sim']);
    return json({ ok: true, nome: nome, novo: true });
  } catch (err) { return json({ ok: false, erro: String(err) }); }
}

/* gerar prova: lê o arquivo (PDF, imagem ou texto) e devolve as questões para a tela revisar */
function gerarProva(d) {
  try {
    if (String(d.chave || '') !== ARQ_SEGREDO) return json({ ok: false, erro: 'não autorizado' });
    if (!GEMINI_API_KEY) return json({ ok: false, erro: 'A IA não está configurada (falta a chave do Gemini no servidor do app).' });
    var n = Math.max(3, Math.min(30, Number(d.n) || 10));
    var converter = d.modo === 'converter';
    var partes = [];
    var url = String(d.arquivo || '');
    if (url) {
      var mime = (url.match(/^data:([^;]+);/) || [])[1] || '';
      var b64 = url.replace(/^data:[^;]+;base64,/, '');
      if (mime.indexOf('image') < 0 && mime.indexOf('pdf') < 0) return json({ ok: false, erro: 'Só leio PDF ou imagem direto; os outros formatos chegam como texto.' });
      partes.push({ inline_data: { mime_type: mime, data: b64 } });
    }
    var texto = String(d.texto || '').slice(0, 400000);
    if (texto) partes.push({ text: 'CONTEÚDO DO ARQUIVO:\n' + texto });
    if (!partes.length) return json({ ok: false, erro: 'Arquivo vazio.' });
    var tema = String(d.titulo || '').slice(0, 120);
    var prompt = converter
      ? 'O arquivo anexo já é uma prova (ou lista de questões) usada no treinamento de colaboradores de uma rede de lojas de tintas no Brasil (Só Tintas). ' +
        'Transcreva TODAS as questões de múltipla escolha que encontrar, sem inventar nenhuma. Se houver gabarito, use-o; se não houver, marque a alternativa certa pelo conteúdo. ' +
        'Questões com mais de 4 alternativas: mantenha a certa e as 3 erradas mais plausíveis. Questões abertas ou de verdadeiro/falso: transforme em 4 alternativas.'
      : 'Você monta provas de treinamento para vendedores e equipe de loja de uma rede de lojas de tintas no Brasil (Só Tintas). ' +
        'A partir do material anexo' + (tema ? ' (tema: ' + tema + ')' : '') + ', crie ' + n + ' questões de múltipla escolha que confiram se a pessoa entendeu o que é importante para o dia a dia da loja ' +
        '(atendimento, produto, aplicação, processo). Use só o que está no material: nada de fatos de fora. Varie a dificuldade, evite pegadinhas e alternativas do tipo "todas as anteriores".';
    prompt += '\n\nResponda APENAS com JSON válido, sem markdown, no formato:\n' +
      '{"titulo":"título curto da prova","questoes":[{"enunciado":"...","opcoes":["A","B","C","D"],"correta":0,"explicacao":"por que a certa é a certa, em 1 frase"}]}\n' +
      'Regras: exatamente 4 opções por questão; "correta" é o índice (0 a 3) da opção certa; distribua a posição da certa entre as quatro; português do Brasil; enunciado com no máximo 300 caracteres.';
    partes.unshift({ text: prompt });
    var r = chamarGemini(partes, 16000, 0.4);
    if (r.erro) return json({ ok: false, erro: r.erro });
    var bruto = (String(r.texto || '').match(/\{[\s\S]*\}/) || [''])[0];
    if (!bruto) return json({ ok: false, erro: 'A IA não devolveu as questões. Tente de novo ou use um arquivo menor.' });
    var o = JSON.parse(bruto), Q = [];
    (o.questoes || []).forEach(function (q) {
      var ops = (q.opcoes || []).map(function (x) { return String(x || '').trim(); }).filter(Boolean).slice(0, 4);
      var c = Number(q.correta);
      if (!q.enunciado || ops.length < 2 || !(c >= 0 && c < ops.length)) return;
      Q.push({ enunciado: String(q.enunciado).trim(), opcoes: ops, correta: c, explicacao: String(q.explicacao || '').trim() });
    });
    if (!Q.length) return json({ ok: false, erro: 'Não encontrei questões nesse arquivo.' });
    return json({ ok: true, titulo: String(o.titulo || tema || '').trim(), questoes: Q, cortado: !!r.cortado });
  } catch (err) { return json({ ok: false, erro: String(err && err.message || err) }); }
}
